<script setup>
import { ref, onMounted } from 'vue'
import { useAuthStore } from '../stores/auth'
import { useRouter } from 'vue-router'
import { apiGet, apiPost, apiGetJSON, apiPostJSON, apiPut } from '../utils/request'

const auth = useAuthStore()
const router = useRouter()
const props = defineProps(['isDark'])
const emit = defineEmits(['rewarded'])

const ads = ref([])
const loading = ref(true)
const watchingAd = ref(null)
const countdown = ref(0)
let timer = null

onMounted(async () => {
  try {
    const data = await apiGetJSON('/api/ads/active')
    ads.value = data.items || []
  } catch (e) {
    console.error('Failed to load ads:', e)
  } finally {
    loading.value = false
  }
})

async function watchAd(ad) {
  try {
    await apiPost(`/api/ads/${ad.id}/watch`)
    watchingAd.value = ad
    countdown.value = ad.watch_duration
    timer = setInterval(() => {
      countdown.value--
      if (countdown.value <= 0) clearInterval(timer)
    }, 1000)
  } catch (e) {
    alert('开始观看失败')
  }
}

async function claimReward() {
  try {
    const data = await apiPostJSON(`/api/ads/${watchingAd.value.id}/complete`, { duration: watchingAd.value.watch_duration })
    if (data.rewarded) {
      emit('rewarded', data)
    } else if (data.error) {
      alert(data.error)
    }
  } catch (e) {
    alert('领取失败')
  }
  closeAd()
}

function closeAd() {
  watchingAd.value = null
  if (timer) clearInterval(timer)
  countdown.value = 0
}
</script>
